import { useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Link, Route, Router as WouterRouter, Switch, useLocation, useParams } from 'wouter';
import { ArrowRight, BarChart3, Bell, BookOpen, BrainCircuit, Check, ChevronRight, CircleHelp, Clock3, CloudUpload, Compass, FileCheck2, Flower2, Gauge, Goal, GraduationCap, Leaf, LineChart, LogIn, MessageCircle, MoreHorizontal, Network, Play, Plus, RotateCcw, Search, Send, Settings2, ShieldCheck, Sparkles, Sprout, Target, TrendingUp, Upload, Users, X, Zap } from 'lucide-react';
import { useGetAchievements, useGetAnalytics, useGetCompetency, useGetCourse, useGetCourses, useGetDashboard, useGetGarden, useGetIntegrations, useGetProfile, useGetRecommendations, useGetSkillDna, useGenerateQuiz, useGetQuiz, useLogin, useRecordLearningTime, useSubmitAssessment, useSubmitQuiz } from '@workspace/api-client-react';
